-- ── Accessors ───────────────────────────────────────────────────────────
-- Emitted from the importer template, not hand-written: this file is
-- overwritten wholesale on every pipeline run (CLAUDE.md).

function CodexData:GetDecorIDForItem(itemID)
    itemID = tonumber(itemID)
    return itemID and ItemToDecor[itemID] or nil
end

function CodexData:GetItemIDForDecor(decorID)
    decorID = tonumber(decorID)
    return decorID and DecorToItem[decorID] or nil
end

function CodexData:GetDecorAttributes(decorID)
    decorID = tonumber(decorID)
    return decorID and Attributes[decorID] or nil
end

-- Housing placement budget cost. Returns nil rather than 0 when unknown,
-- so a caller summing a shopping list can tell 'free' from 'no idea'.
function CodexData:GetDecorBudgetCost(decorID)
    local attrs = self:GetDecorAttributes(decorID)
    return attrs and attrs.budget or nil
end

-- Decor size band: "Tiny" | "Small" | "Medium" | "Large" | "Huge".
function CodexData:GetDecorSize(decorID)
    local attrs = self:GetDecorAttributes(decorID)
    return attrs and attrs.size or nil
end

-- Colour tags for this decor, e.g. { "Dark Brown", "Olive" }. Returns an
-- empty table rather than nil so callers can iterate unconditionally.
function CodexData:GetDecorColors(decorID)
    local attrs = self:GetDecorAttributes(decorID)
    return (attrs and attrs.colors) or {}
end

-- Vendor cost as (amount, currencyID) for decor bought with something
-- other than gold. Villa's vendor assistant reports extended-cost slots
-- as UNPRICED because the merchant API gives it no gold value; this is
-- what lets those be priced instead of merely counted.
function CodexData:GetDecorCurrency(decorID)
    local attrs = self:GetDecorAttributes(decorID)
    if not attrs or not attrs.currencyType then
        return nil
    end
    return attrs.currency, attrs.currencyType
end

-- Every distinct colour tag in the index, sorted. Built on first use so
-- a filter dropdown does not have to hardcode the list.
local _colorList
function CodexData:GetAllDecorColors()
    if _colorList then return _colorList end
    local seen, list = {}, {}
    for _, attrs in pairs(Attributes) do
        for _, color in ipairs(attrs.colors or {}) do
            if not seen[color] then
                seen[color] = true
                list[#list + 1] = color
            end
        end
    end
    table.sort(list)
    _colorList = list
    return list
end
